sources['com/zte/mifavor/views/MFVBatteryViewLayout.java']='''package com.zte.mifavor.views;import android.widget.*;import de.robv.android.xposed.XposedBridge;public class MFVBatteryViewLayout extends RelativeLayout {public int preference=2;public FrameLayout mBatteryContainer=new FrameLayout();public MFVBatteryMeterView mBatteryIconView=new MFVBatteryMeterView();public TextView mBatteryLevelInsideView=new TextView(),mBatteryLevelOutsideView=new TextView();public ChargeIndicator mInsideChargeView=new ChargeIndicator(),mOutsideChargeView=new ChargeIndicator();public MFVBatteryViewLayout(){mBatteryContainer.parent=this;mBatteryIconView.parent=mBatteryContainer;mBatteryLevelInsideView.parent=mBatteryContainer;mInsideChargeView.parent=mBatteryContainer;mBatteryLevelOutsideView.parent=this;mOutsideChargeView.parent=this;}public int getLevelDisplayMode(){return preference;}public void updateBatteryLayout(int mode,boolean force){XposedBridge.run(this,MFVBatteryViewLayout.class,"updateBatteryLayout",new Class<?>[]{int.class,boolean.class},new Object[]{mode,force},()->{mBatteryLevelInsideView.visibility=mode==1?0:8;mBatteryLevelOutsideView.visibility=mode==2?0:8;mInsideChargeView.visibility=mBatteryIconView.mIsCharing?0:8;mOutsideChargeView.visibility=8;});}public void updateBatteryLevelText(){XposedBridge.run(this,MFVBatteryViewLayout.class,"updateBatteryLevelText",new Class<?>[]{},new Object[]{},()->{mBatteryLevelInsideView.text=""+mBatteryIconView.mBateryLevel;mBatteryLevelOutsideView.text=mBatteryIconView.mBateryLevel+"%";});}public void onFinishInflate(){XposedBridge.run(this,MFVBatteryViewLayout.class,"onFinishInflate",new Class<?>[]{},new Object[]{},()->updateBatteryLayout(preference,true));}}'''
sources['com/android/systemui/statusbar/StatusBarIconView.java']='''package com.android.systemui.statusbar;import de.robv.android.xposed.XposedBridge;public class StatusBarIconView extends android.widget.ImageView {public boolean notification=true,blocked;public int visible=1,mDecorColor=42;public float mDotAppearAmount=1;public boolean isNotification(){return notification;}public boolean isIconBlocked(){return blocked;}public int getVisibleState(){return visible;}@Override public void onDraw(android.graphics.Canvas c){XposedBridge.run(this,StatusBarIconView.class,"onDraw",new Class<?>[]{android.graphics.Canvas.class},new Object[]{c},()->c.draws++);}}'''
sources['com/android/systemui/statusbar/phone/NotificationIconContainer.java']='''package com.android.systemui.statusbar.phone;import de.robv.android.xposed.XposedBridge;public class NotificationIconContainer extends android.view.ViewGroup {public Object mIsolatedIcon;public java.util.HashMap<android.view.View,IconState> mIconStates=new java.util.HashMap<>();public int lastMaximum,refreshes;public static class IconState{public boolean hidden;public float iconAppearAmount=1;public int visibleState=2;}public boolean shouldForceOverflow(int index,int bump,float amount,int maximum){Object[] args={index,bump,amount,maximum};return (Boolean)XposedBridge.call(this,NotificationIconContainer.class,"shouldForceOverflow",new Class<?>[]{int.class,int.class,float.class,int.class},args,()->{lastMaximum=(Integer)args[3];return index>=lastMaximum&&amount>0;});}public void calculateIconXTranslations(){XposedBridge.run(this,NotificationIconContainer.class,"calculateIconXTranslations",new Class<?>[]{},new Object[]{},()->{});}public void updateState(){refreshes++;calculateIconXTranslations();}}'''
sources['com/elitedarkkaiser/nubialy/xposed/IconControlsTest.java']='''package com.elitedarkkaiser.nubialy.xposed;import android.graphics.*;public class IconControlsTest {static void check(boolean v){if(!v)throw new AssertionError(BatteryControlBackend.status()+NotificationIconBackend.status());}public static void main(String[] args){ClassLoader loader=IconControlsTest.class.getClassLoader();BatteryControlBackend.install(loader);var root=new com.android.systemui.statusbar.phone.PhoneStatusBarView();var battery=new com.zte.mifavor.views.MFVBatteryViewLayout();battery.parent=root;battery.onFinishInflate();BatteryControlBackend.begin(1,1);check(battery.mBatteryLevelInsideView.visibility==0&&battery.mBatteryLevelOutsideView.visibility==8);check(battery.mBatteryLevelInsideView.text.equals("76"));battery.mBatteryIconView.mIsCharing=true;battery.mInsideChargeView.updateVisibility(true);check(battery.mInsideChargeView.visibility==8);battery.mBatteryIconView.mBateryLevel=54;battery.updateBatteryLevelText();check(battery.mBatteryLevelInsideView.text.equals("54"));BatteryControlBackend.begin(2,0);check(battery.mBatteryLevelInsideView.visibility==8&&battery.mBatteryLevelOutsideView.visibility==0&&battery.mBatteryLevelOutsideView.text.equals("54%"));BatteryControlBackend.begin(3,0);check(battery.mBatteryLevelInsideView.visibility==8&&battery.mBatteryLevelOutsideView.visibility==8);battery.preference=1;check(BatteryControlBackend.end());check(battery.mBatteryLevelInsideView.visibility==0&&battery.mInsideChargeView.visibility==0);BatteryControlBackend.begin(2,1);battery.mBatteryIconView.mOemChargeType=128;battery.updateBatteryLevelText();check(battery.mBatteryLevelInsideView.visibility==0&&battery.mInsideChargeView.visibility==0);battery.mBatteryIconView.mOemChargeType=0;battery.parent=null;battery.updateBatteryLayout(1,true);check(battery.mBatteryLevelInsideView.visibility==0);battery.parent=root;battery.mBatteryIconView.mType.status=false;battery.updateBatteryLayout(1,true);check(battery.mBatteryLevelInsideView.visibility==0);battery.mBatteryIconView.mType.status=true;android.os.Looper.off=true;battery.updateBatteryLayout(1,true);check(battery.mBatteryLevelInsideView.visibility==0);android.os.Looper.off=false;check(BatteryControlBackend.end());
NotificationIconBackend.install(loader);var icons=new com.android.systemui.statusbar.phone.NotificationIconContainer();icons.parent=root;icons.calculateIconXTranslations();NotificationIconBackend.begin(1,3);check(icons.shouldForceOverflow(3,0,1,5)&&icons.lastMaximum==3);icons.shouldForceOverflow(1,0,1,2);check(icons.lastMaximum==2);var dot=new com.android.systemui.statusbar.StatusBarIconView();for(int n=0;n<4;n++){var icon=n==0?dot:new com.android.systemui.statusbar.StatusBarIconView();icon.parent=icons;icons.children.add(icon);icons.mIconStates.put(icon,new com.android.systemui.statusbar.phone.NotificationIconContainer.IconState());}icons.mIconStates.get(icons.children.get(1)).visibleState=0;icons.mIconStates.get(icons.children.get(2)).hidden=true;Canvas c=new Canvas();dot.onDraw(c);check(c.draws==10&&"+2".equals(c.text)&&c.saves==0);dot.visible=0;c=new Canvas();dot.onDraw(c);check(c.draws==1);dot.visible=1;icons.mIsolatedIcon=dot;c=new Canvas();dot.onDraw(c);check(c.draws==1);icons.shouldForceOverflow(3,0,1,5);check(icons.lastMaximum==5);icons.mIsolatedIcon=null;icons.parent=null;c=new Canvas();dot.onDraw(c);check(c.draws==1);icons.parent=root;android.os.Looper.off=true;c=new Canvas();dot.onDraw(c);check(c.draws==1);android.os.Looper.off=false;check(NotificationIconBackend.end());icons.shouldForceOverflow(3,0,1,5);check(icons.lastMaximum==5);c=new Canvas();dot.onDraw(c);check(c.draws==1);check(BatteryControlBackend.healthy()&&NotificationIconBackend.healthy());System.out.println("Battery placement/charging/current-state restoration and notification overflow thresholds/count/scope passed");}}'''
with tempfile.TemporaryDirectory(prefix='nubialy-icon-controls-') as work:
 folder=Path(work)
 for name,content in sources.items():
  f=folder/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(content)
 files=[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy/xposed/QsHeaderScope.java')]+[str(p) for p in folder.rglob('*.java')]+[str(root/'app/src/main/java/com/elitedarkkaiser/nubialy'/n) for n in ['xposed/BatteryControlBackend.java','xposed/NotificationIconBackend.java']]
 subprocess.run(['java','com.sun.tools.javac.Main','-d',str(folder/'classes'),*files],check=True)
 subprocess.run(['java','-cp',str(folder/'classes'),'com.elitedarkkaiser.nubialy.xposed.IconControlsTest'],check=True)
